INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c25dd291-a35b-52bd-b094-820e50ab8ee7', 'Switzerland Register relating to Pollutant Release and the Transfer', 'Ordinance on the Register relating to Pollutant Release and the Transfer of Waste and of Pollutants in Waste Water', 'This ordinance is intended to guarantee public access to information on pollutant release and the transfer of waste and of pollutants in waste water by means of a register.', 'This ordinance is intended to guarantee public access to information on pollutant release and the transfer of waste and of pollutants in waste water by means of a register.', 'This ordinance is intended to guarantee public access to information on pollutant release and the transfer of waste and of pollutants in waste water by means of a register.', 'Switzerland', 'circularity', 'in_force', '2007-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_15', ARRAY['regulations', 'mandatory', 'sdg6', 'switzerland', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ea5fb1e-0788-596d-a74b-d6ae0d305041', 'Switzerland information relating to corporate governannce (Corporate Governance Directive', 'Directive on information relating to corporate governannce (Corporate Governance Directive, DGC)', 'The directive is intended to encourage issuers to make two certain key information relating to corporate governance available to investors in an appropriate form.', 'The directive is intended to encourage issuers to make two certain key information relating to corporate governance available to investors in an appropriate form.', 'The directive is intended to encourage issuers to make two certain key information relating to corporate governance available to investors in an appropriate form.', 'Switzerland', 'governance', 'in_force', '2002-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_8', ARRAY['regulations', 'mandatory', 'switzerland', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c99c892f-dda2-557b-86db-2212652037e4', 'Taiwan Sustainable Taxonomy', 'Taiwan Sustainable Taxonomy, 2023', 'The Taiwan Sustainable Taxonomy is established to encourage financial institutions to direct funding towards sustainable economic activities, empower sustainable development, facilitate the low-carbon transition of companies, and help companies and financial institutions identify sustainable economic activities.', 'The Taiwan Sustainable Taxonomy is established to encourage financial institutions to direct funding towards sustainable economic activities, empower sustainable development, facilitate the low-carbon transition of companies, and help companies and financial institutions identify sustainable economic activities.', 'The Taiwan Sustainable Taxonomy is established to encourage financial institutions to direct funding towards sustainable economic activities, empower sustainable development, facilitate the low-carbon transition of companies, and help companies and financial institutions identify sustainable economic activities.', 'Taiwan', 'climate', 'in_force', '2023-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_30', ARRAY['sdg13', 'taiwan', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eda551cb-ba64-5fb6-b98b-0488cd1faa88', 'Taiwan Air Pollution Control Fee Collection Regulations', 'Air Pollution Control Fee Collection Regulations', 'The aim of the Air Pollution Control Fee Collection Regulations is to collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. The value of the air pollution control fees is based on the type and quantity of air pollutants. Fuel vendors or importers shall fill out an air pollution control fee report form and payment form, pay the air pollution control fee for the previous month to the financial institution account, and make a filing with the central competent authority via the internet before the fifteenth day of each month. Additionally, the owner, manager or actual user of the stationary pollution source shall complete an air pollution control fee report form and payment form, pay the air pollution control fee for the previous quarter to the financial institution account, and make a filing with the central competent authority via the internet before the last day of April, July, October and January each year.', 'The aim of the Air Pollution Control Fee Collection Regulations is to collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. The value of the air pollution control fees is based on the type and quantity of air pollutants. Fuel vendors or importers shall fill out an air pollution control fee report form and payment form, pay the air pollution control fee for the previous month to the financial institution account, and make a filing with the central competent authority via the internet before the fifteenth day of each month. Additionally, the owner, manager or actual user of the stationary pollution source shall complete an air pollution control fee report form and payment form, pay the air pollution control fee for the previous quarter to the financial institution account, and make a filing with the central competent authority via the internet before the last day of April, July, October and January each year.', 'The aim of the Air Pollution Control Fee Collection Regulations is to collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. The value of the air pollution control fees is based on the type and quantity of air pollutants. Fuel vendors or importers shall fill out an air pollution control fee report form and payment form, pay the air pollution control fee for the previous month to the financial institution account, and make a filing with the central competent authority via the internet before the fifteenth day of each month. Additionally, the owner, manager or actual user of the stationary pollution source shall complete an air pollution control fee report form and payment form, pay the air pollution control fee for the previous quarter to the financial institution account, and make a filing with the central competent authority via the internet before the last day of April, July, October and January each year.', 'Taiwan', 'climate', 'in_force', '2022-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_18', ARRAY['taiwan', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a0fbbbf3-9d0b-5788-923b-b436f4492254', 'Taiwan Water Pollution Control Measures and Test Reporting Management', 'Water Pollution Control Measures and Test Reporting Management Regulations', 'Water Pollution Control Measures and Test Reporting Management Regulations is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Chapter 11 of the Test Reporting Management, an enterprise or sewage system that is connected to the sewage system, unless exempt according to Article 71, shall submit test reports. All of reporting criteria for the test reports are outlined in Articles 71 to Article 94.', 'Water Pollution Control Measures and Test Reporting Management Regulations is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Chapter 11 of the Test Reporting Management, an enterprise or sewage system that is connected to the sewage system, unless exempt according to Article 71, shall submit test reports. All of reporting criteria for the test reports are outlined in Articles 71 to Article 94.', 'Water Pollution Control Measures and Test Reporting Management Regulations is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Chapter 11 of the Test Reporting Management, an enterprise or sewage system that is connected to the sewage system, unless exempt according to Article 71, shall submit test reports. All of reporting criteria for the test reports are outlined in Articles 71 to Article 94.', 'Taiwan', 'climate', 'in_force', '2022-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_29', ARRAY['regulations', 'taiwan', 'mandatory', 'sdg6', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('28a560aa-1f56-58b1-a196-5a700e0d8a27', 'Taiwan Revision of Stewardship Principles for Institutional Investors', 'Revision of Stewardship Principles for Institutional Investors, 2020', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfill their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfill their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfill their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'Taiwan', 'governance', 'in_force', '2020-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_16', ARRAY['taiwan', 'guidance_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('187bde30-f3c2-54f2-a802-e4d690b46c01', 'Taiwan 2020 Corporate Governance Evaluation System', 'The 2020 Corporate Governance Evaluation System', 'The purpose of this roadmap is to provide comparisons of corporate governance performance among all listed companies so that investors and companies can better understand how well specific companies are implementing corporate governance.', 'The purpose of this roadmap is to provide comparisons of corporate governance performance among all listed companies so that investors and companies can better understand how well specific companies are implementing corporate governance.', 'The purpose of this roadmap is to provide comparisons of corporate governance performance among all listed companies so that investors and companies can better understand how well specific companies are implementing corporate governance.', 'Taiwan', 'governance', 'in_force', '2020-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_2', ARRAY['other sustainability policy', 'taiwan', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b40eb608-7ccf-55a3-ae04-0a35f67691c7', 'Taiwan Company Act', 'Taiwan Company Act', 'Article 20 of the Company Act requires all companies in Taiwan to produce a business report, financial statements, and the surplus earnings distribution or loss make-up proposal at the end of each fiscal year. If the amount of equity capital surpasses the figure defined by the competent authority, the company shall have their financial statements audited by a certified public accountant. The business report, financial statements, and profit and loss proposal shall be submitted to the shareholders of the company for their approval 30 days before the general meeting.', 'Article 20 of the Company Act requires all companies in Taiwan to produce a business report, financial statements, and the surplus earnings distribution or loss make-up proposal at the end of each fiscal year. If the amount of equity capital surpasses the figure defined by the competent authority, the company shall have their financial statements audited by a certified public accountant. The business report, financial statements, and profit and loss proposal shall be submitted to the shareholders of the company for their approval 30 days before the general meeting.', 'Article 20 of the Company Act requires all companies in Taiwan to produce a business report, financial statements, and the surplus earnings distribution or loss make-up proposal at the end of each fiscal year. If the amount of equity capital surpasses the figure defined by the competent authority, the company shall have their financial statements audited by a certified public accountant. The business report, financial statements, and profit and loss proposal shall be submitted to the shareholders of the company for their approval 30 days before the general meeting.', 'Taiwan', 'climate', 'in_force', '2020-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_26', ARRAY['taiwan', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('320cb42f-2f0b-51e6-afd5-208a54414a8d', 'Taiwan Occupational Safety and Health Act', 'Occupational Safety and Health Act', 'The aim of the Occupational Safety and Health Act is to protect workers’ safety and health and to prevent occupational accidents. According to Article 38, employers in industries designated by the central competent authority shall compile reports and statistics on occupational accidents in accordance with regulations, and forward such reports to the labor inspection agencies each month for future reference and post them in the workplace.', 'The aim of the Occupational Safety and Health Act is to protect workers’ safety and health and to prevent occupational accidents. According to Article 38, employers in industries designated by the central competent authority shall compile reports and statistics on occupational accidents in accordance with regulations, and forward such reports to the labor inspection agencies each month for future reference and post them in the workplace.', 'The aim of the Occupational Safety and Health Act is to protect workers’ safety and health and to prevent occupational accidents. According to Article 38, employers in industries designated by the central competent authority shall compile reports and statistics on occupational accidents in accordance with regulations, and forward such reports to the labor inspection agencies each month for future reference and post them in the workplace.', 'Taiwan', 'climate', 'in_force', '2019-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_22', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'taiwan', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54103b8b-8246-516a-9409-45975e316acc', 'Taiwan Renewable Energy Development Act', 'Renewable Energy Development Act', 'The purpose of the Renewable Energy Development Act is to encourage renewable energy use, promote energy diversification, improve environmental quality, assist relevant industries and enhance sustainable development of the country. Businesses that are equipped with self-use power generating facilities exceeding a certain installed capacity shall compile its business conditions into abbreviated monthly reports and further compile annual reports within three months after the end of each business year.', 'The purpose of the Renewable Energy Development Act is to encourage renewable energy use, promote energy diversification, improve environmental quality, assist relevant industries and enhance sustainable development of the country. Businesses that are equipped with self-use power generating facilities exceeding a certain installed capacity shall compile its business conditions into abbreviated monthly reports and further compile annual reports within three months after the end of each business year.', 'The purpose of the Renewable Energy Development Act is to encourage renewable energy use, promote energy diversification, improve environmental quality, assist relevant industries and enhance sustainable development of the country. Businesses that are equipped with self-use power generating facilities exceeding a certain installed capacity shall compile its business conditions into abbreviated monthly reports and further compile annual reports within three months after the end of each business year.', 'Taiwan', 'climate', 'in_force', '2019-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_25', ARRAY['regulations', 'sdg7', 'taiwan', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('337321a5-b5a1-5f79-8620-646c32771b6b', 'Taiwan Air Pollution Control Act', 'Air Pollution Control Act', 'This Act is formulated to control air pollution, maintain public health and the living environment, and improve the quality of life. According to the Article 16, competent authorities at all levels may collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. According to the Article 21, those public and private premises possessing stationary pollution sources designated and officially announced by the central competent authority shall report their annual air pollutant emissions quantities of their stationary pollution sources for the previous year to the local competent authority before the end of January each year.', 'This Act is formulated to control air pollution, maintain public health and the living environment, and improve the quality of life. According to the Article 16, competent authorities at all levels may collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. According to the Article 21, those public and private premises possessing stationary pollution sources designated and officially announced by the central competent authority shall report their annual air pollutant emissions quantities of their stationary pollution sources for the previous year to the local competent authority before the end of January each year.', 'This Act is formulated to control air pollution, maintain public health and the living environment, and improve the quality of life. According to the Article 16, competent authorities at all levels may collect air pollution control fees from stationary and mobile pollution sources that emit air pollutants. According to the Article 21, those public and private premises possessing stationary pollution sources designated and officially announced by the central competent authority shall report their annual air pollutant emissions quantities of their stationary pollution sources for the previous year to the local competent authority before the end of January each year.', 'Taiwan', 'climate', 'in_force', '2018-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_17', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'taiwan', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0949359-154a-550e-b79b-92734eec134c', 'Taiwan Environmental Impact Assessment Act Enforcement Rules', 'Environmental Impact Assessment Act Enforcement Rules', 'The aim of the Environmental Impact Assessment Act Enforcement Rules is to prevent and mitigate the adverse impact of development activity on the environment in order to achieve the goal of environmental protection. For those development activities for which environmental impact assessments are required, the developer, when planning, shall, in accordance with environmental impact assessment working standards, conduct a Phase 1 environmental impact assessment and prepare an environmental impact statement. A forecast of the environmental impacts that could possibly be caused by the development activity ?and environmental protection strategies and alternate plans are to be included.', 'The aim of the Environmental Impact Assessment Act Enforcement Rules is to prevent and mitigate the adverse impact of development activity on the environment in order to achieve the goal of environmental protection. For those development activities for which environmental impact assessments are required, the developer, when planning, shall, in accordance with environmental impact assessment working standards, conduct a Phase 1 environmental impact assessment and prepare an environmental impact statement. A forecast of the environmental impacts that could possibly be caused by the development activity ?and environmental protection strategies and alternate plans are to be included.', 'The aim of the Environmental Impact Assessment Act Enforcement Rules is to prevent and mitigate the adverse impact of development activity on the environment in order to achieve the goal of environmental protection. For those development activities for which environmental impact assessments are required, the developer, when planning, shall, in accordance with environmental impact assessment working standards, conduct a Phase 1 environmental impact assessment and prepare an environmental impact statement. A forecast of the environmental impacts that could possibly be caused by the development activity ?and environmental protection strategies and alternate plans are to be included.', 'Taiwan', 'governance', 'in_force', '2018-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_20', ARRAY['taiwan', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e26926ff-3d56-5139-8897-9b110b67d573', 'Taiwan Water Pollution Control Act', 'Water Pollution Control Act', 'This Act is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Article 22, enterprises or sewage systems shall report the operation of wastewater and sewage treatment facilities, analysis of effluent water quality and water volume, power consumption records, and other documents related to wastewater and sewage treatment to the appropriate local authority.', 'This Act is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Article 22, enterprises or sewage systems shall report the operation of wastewater and sewage treatment facilities, analysis of effluent water quality and water volume, power consumption records, and other documents related to wastewater and sewage treatment to the appropriate local authority.', 'This Act is formulated to control water pollution and ensure the cleanliness of water resources in order to maintain ecological systems, enhance the living environment and advance public health. According to the Article 22, enterprises or sewage systems shall report the operation of wastewater and sewage treatment facilities, analysis of effluent water quality and water volume, power consumption records, and other documents related to wastewater and sewage treatment to the appropriate local authority.', 'Taiwan', 'climate', 'in_force', '2018-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_28', ARRAY['regulations', 'taiwan', 'mandatory', 'sdg6', 'sdg12', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4166fabc-fe6e-5434-a644-f8a520d5594a', 'Taiwan Corporate Governance Best Practice Principles for TWSE/TPEx Listed', 'Corporate Governance Best Practice Principles for TWSE/TPEx Listed , 2018', 'The Taiwan Stock Exchange Corporation (TWSE) and the Taipei Exchange (TPEx) hereby jointly adopt these Principles, to be followed by TWSE and TPEx listed companies, to assist them in establishing sound corporate governance systems and promote sound development of the securities market.', 'The Taiwan Stock Exchange Corporation (TWSE) and the Taipei Exchange (TPEx) hereby jointly adopt these Principles, to be followed by TWSE and TPEx listed companies, to assist them in establishing sound corporate governance systems and promote sound development of the securities market.', 'The Taiwan Stock Exchange Corporation (TWSE) and the Taipei Exchange (TPEx) hereby jointly adopt these Principles, to be followed by TWSE and TPEx listed companies, to assist them in establishing sound corporate governance systems and promote sound development of the securities market.', 'Taiwan', 'governance', 'in_force', '2018-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_5', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1db51363-c033-5862-ba36-152f1b7687ae', 'Taiwan Corporate Governance Roadmap', 'Corporate Governance Roadmap (2018-2020)', 'The Roadmap intends to encourage active participation of companies and investors in corporate governance, through deepening corporate governance culture, enhancing board functions, strengthening information transparency, encouraging participation of external shareholders, and augmenting regulatory enforcement.', 'The Roadmap intends to encourage active participation of companies and investors in corporate governance, through deepening corporate governance culture, enhancing board functions, strengthening information transparency, encouraging participation of external shareholders, and augmenting regulatory enforcement.', 'The Roadmap intends to encourage active participation of companies and investors in corporate governance, through deepening corporate governance culture, enhancing board functions, strengthening information transparency, encouraging participation of external shareholders, and augmenting regulatory enforcement.', 'Taiwan', 'governance', 'in_force', '2018-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_6', ARRAY['other sustainability policy', 'taiwan', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f0ac58d-1654-59ba-b01d-6cbef8dfdc63', 'Taiwan Corporate Governance Best-Practice Principles for Securities Firms', 'Corporate Governance Best-Practice Principles for Securities Firms, 2017', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'Taiwan', 'governance', 'in_force', '2017-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_14', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
