INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b3b88af0-a248-5005-9ce6-ae698017d55d', 'Taiwan Public and Private Premises Possessing Stationary Pollution Sources', 'Public and Private Premises Possessing Stationary Pollution Sources Emissions Reporting Management Regulations', 'The aim of the Public and Private Premises Possessing Stationary Pollution Sources Emissions Reporting Management Regulations is to report the annual air pollutant emissions quantities of their stationary pollution sources. Public and private premises with stationary pollution sources that emit air pollutants shall report its air pollutant emissions quantities, including particulate pollutants, SOx, NOx, VOCs, etc., using an online platform before the last day of April, July, and October of each year and January of the following year.', 'The aim of the Public and Private Premises Possessing Stationary Pollution Sources Emissions Reporting Management Regulations is to report the annual air pollutant emissions quantities of their stationary pollution sources. Public and private premises with stationary pollution sources that emit air pollutants shall report its air pollutant emissions quantities, including particulate pollutants, SOx, NOx, VOCs, etc., using an online platform before the last day of April, July, and October of each year and January of the following year.', 'The aim of the Public and Private Premises Possessing Stationary Pollution Sources Emissions Reporting Management Regulations is to report the annual air pollutant emissions quantities of their stationary pollution sources. Public and private premises with stationary pollution sources that emit air pollutants shall report its air pollutant emissions quantities, including particulate pollutants, SOx, NOx, VOCs, etc., using an online platform before the last day of April, July, and October of each year and January of the following year.', 'Taiwan', 'climate', 'in_force', '2017-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_23', ARRAY['sdg13', 'regulations', 'taiwan', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6c5ccb5f-a168-5e73-be36-cb918ae9224f', 'Taiwan Waste Disposal Act', 'Waste Disposal Act', 'The Waste Disposal Act is formulated for the effective clearance and disposal of waste, improvement of environmental sanitation and maintenance of public health. According to the Article 31, enterprises of a certain size that is designated and officially announced by the central competent authority shall perform the following matters within a certain time period demanded by the official announcement - it shall report (a) the basic information, (b)the  type and quantities of general waste, (c) the quantities of general waste stored in the enterprise, and (d) the clearance, disposal, reuse, and output of general waste.', 'The Waste Disposal Act is formulated for the effective clearance and disposal of waste, improvement of environmental sanitation and maintenance of public health. According to the Article 31, enterprises of a certain size that is designated and officially announced by the central competent authority shall perform the following matters within a certain time period demanded by the official announcement - it shall report (a) the basic information, (b)the  type and quantities of general waste, (c) the quantities of general waste stored in the enterprise, and (d) the clearance, disposal, reuse, and output of general waste.', 'The Waste Disposal Act is formulated for the effective clearance and disposal of waste, improvement of environmental sanitation and maintenance of public health. According to the Article 31, enterprises of a certain size that is designated and officially announced by the central competent authority shall perform the following matters within a certain time period demanded by the official announcement - it shall report (a) the basic information, (b)the  type and quantities of general waste, (c) the quantities of general waste stored in the enterprise, and (d) the clearance, disposal, reuse, and output of general waste.', 'Taiwan', 'climate', 'in_force', '2017-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_27', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'mandatory', 'sdg6', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ffeabf0-4781-5f76-a0ae-6f5777c615c9', 'Taiwan Stewardship Principles for Institutional Investors', 'Stewardship Principles for Institutional Investors, 2016', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfil their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfil their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'The Principles, through provision of a principle-based framework and guidance, are intended to encourage institutional investors to apply their expertise and influence, and fulfil their duties as asset owners or managers, so as to enhance long-term value for themselves and capital providers.', 'Taiwan', 'governance', 'in_force', '2016-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_12', ARRAY['taiwan', 'guidance_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d5e2a06d-4616-55c5-af51-35930edfb125', 'Taiwan Energy Administration Act', 'Energy Administration Act', 'The aim of the Energy Administration Act is to serve the purpose of upgrading energy administration aimed at rational and efficient utilization of energy. As stipulated in Article 12, energy users whose contract capacity is more than 800KW shall report energy consumption data, including the categories, quantities, items, efficiency, period and methods for the submission of energy consumption.', 'The aim of the Energy Administration Act is to serve the purpose of upgrading energy administration aimed at rational and efficient utilization of energy. As stipulated in Article 12, energy users whose contract capacity is more than 800KW shall report energy consumption data, including the categories, quantities, items, efficiency, period and methods for the submission of energy consumption.', 'The aim of the Energy Administration Act is to serve the purpose of upgrading energy administration aimed at rational and efficient utilization of energy. As stipulated in Article 12, energy users whose contract capacity is more than 800KW shall report energy consumption data, including the categories, quantities, items, efficiency, period and methods for the submission of energy consumption.', 'Taiwan', 'climate', 'in_force', '2016-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_19', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'taiwan', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46b87661-99a0-5819-9a57-32a4e899d3d1', 'Taiwan Adoption of Codes of Ethical Conduct for TWSE/GTSM', 'Guidelines for the Adoption of Codes of Ethical Conduct for TWSE/GTSM Listed Companies, 2015', 'The aim of the Guidelines are adopted for the purpose of encouraging directors, supervisors, and managerial officers of companies listed on the Taiwan Stock Exchange (TWSE) or Taipei Exchange (TPEx) (including general managers or their equivalents, assistant general managers or their equivalents, deputy assistant general managers or their equivalents, chief financial and chief accounting officers, and other persons authorized to manage affairs and sign documents on behalf of a company) to act in line with ethical standards, and to help interested parties better understand the ethical standards of such companies. Each TWSE/TPEx listed company is advised to establish a code of ethical conduct with reference to these Guidelines, and it may develop respective codes of ethical conduct for different managerial officers. Taking its individual circumstances and needs into consideration, a TWSE or TPEx listed company shall adopt a code of ethical conduct that addresses at least the following eight matters: 1) Prevention of conflicts of interest; 2) Minimizing incentives to pursue personal gain; 3) Confidentiality; 4) Fair trade; 5) Safeguarding and proper use of company assets; 6) Legal compliance; 7) Encouraging reporting on illegal or unethical activities; and 8) Disciplinary measures.', 'The aim of the Guidelines are adopted for the purpose of encouraging directors, supervisors, and managerial officers of companies listed on the Taiwan Stock Exchange (TWSE) or Taipei Exchange (TPEx) (including general managers or their equivalents, assistant general managers or their equivalents, deputy assistant general managers or their equivalents, chief financial and chief accounting officers, and other persons authorized to manage affairs and sign documents on behalf of a company) to act in line with ethical standards, and to help interested parties better understand the ethical standards of such companies. Each TWSE/TPEx listed company is advised to establish a code of ethical conduct with reference to these Guidelines, and it may develop respective codes of ethical conduct for different managerial officers. Taking its individual circumstances and needs into consideration, a TWSE or TPEx listed company shall adopt a code of ethical conduct that addresses at least the following eight matters: 1) Prevention of conflicts of interest; 2) Minimizing incentives to pursue personal gain; 3) Confidentiality; 4) Fair trade; 5) Safeguarding and proper use of company assets; 6) Legal compliance; 7) Encouraging reporting on illegal or unethical activities; and 8) Disciplinary measures.', 'The aim of the Guidelines are adopted for the purpose of encouraging directors, supervisors, and managerial officers of companies listed on the Taiwan Stock Exchange (TWSE) or Taipei Exchange (TPEx) (including general managers or their equivalents, assistant general managers or their equivalents, deputy assistant general managers or their equivalents, chief financial and chief accounting officers, and other persons authorized to manage affairs and sign documents on behalf of a company) to act in line with ethical standards, and to help interested parties better understand the ethical standards of such companies. Each TWSE/TPEx listed company is advised to establish a code of ethical conduct with reference to these Guidelines, and it may develop respective codes of ethical conduct for different managerial officers. Taking its individual circumstances and needs into consideration, a TWSE or TPEx listed company shall adopt a code of ethical conduct that addresses at least the following eight matters: 1) Prevention of conflicts of interest; 2) Minimizing incentives to pursue personal gain; 3) Confidentiality; 4) Fair trade; 5) Safeguarding and proper use of company assets; 6) Legal compliance; 7) Encouraging reporting on illegal or unethical activities; and 8) Disciplinary measures.', 'Taiwan', 'climate', 'in_force', '2015-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_21', ARRAY['taiwan', 'guidance_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9c6637f-04e8-5874-86a9-b455a75baefe', 'Taiwan Regulations Governing Information to be Published in Annual', 'Regulations Governing Information to be Published in Annual Reports of Public Companies', 'Article 10 (4) (E) of the regulations requires public companies to include the state of the company''s performance of corporate social responsibilities in its annual report. A public company shall disclose the systems and measures that the company has adopted with respect to: environmental protection; community participation; contribution to society; service to society; social and public interests; consumer rights and interests; human rights; safety and health; and other corporate social responsibilities and activities. This information shall be accompanied by the state of implementation. The regulations provide a formal table for disclosure (Table 2-2-2).', 'Article 10 (4) (E) of the regulations requires public companies to include the state of the company''s performance of corporate social responsibilities in its annual report. A public company shall disclose the systems and measures that the company has adopted with respect to: environmental protection; community participation; contribution to society; service to society; social and public interests; consumer rights and interests; human rights; safety and health; and other corporate social responsibilities and activities. This information shall be accompanied by the state of implementation. The regulations provide a formal table for disclosure (Table 2-2-2).', 'Article 10 (4) (E) of the regulations requires public companies to include the state of the company''s performance of corporate social responsibilities in its annual report. A public company shall disclose the systems and measures that the company has adopted with respect to: environmental protection; community participation; contribution to society; service to society; social and public interests; consumer rights and interests; human rights; safety and health; and other corporate social responsibilities and activities. This information shall be accompanied by the state of implementation. The regulations provide a formal table for disclosure (Table 2-2-2).', 'Taiwan', 'climate', 'in_force', '2015-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_24', ARRAY['regulations', 'taiwan', 'sdg11', 'mandatory', 'sdg16', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('096796ae-fbea-5327-a940-3eb4c7fe197c', 'Taiwan Stock Exchange Corporation Rules Governing the Preparation', 'Taiwan Stock Exchange Corporation Rules Governing the Preparation and Filing of Corporate Social Responsibility Reports by TWSE Listed Companies, 2015', 'The TWSE, in conjunction with the new Corporate Governance Roadmap, has announced the amendments to the “Taiwan Stock Exchange Corporation Rules Governing the Preparation and Filing of Corporate Social Responsibility Reports by TWSE Listed Companies.” This provides guidelines on report preparation to enterprises that meet practical needs and be in line with international disclosure trends in order to help enterprises focus on sustainable development and fulfilling corporate social responsibility. The revised Rules shall be implemented from the date of the announcement.', 'The TWSE, in conjunction with the new Corporate Governance Roadmap, has announced the amendments to the “Taiwan Stock Exchange Corporation Rules Governing the Preparation and Filing of Corporate Social Responsibility Reports by TWSE Listed Companies.” This provides guidelines on report preparation to enterprises that meet practical needs and be in line with international disclosure trends in order to help enterprises focus on sustainable development and fulfilling corporate social responsibility. The revised Rules shall be implemented from the date of the announcement.', 'The TWSE, in conjunction with the new Corporate Governance Roadmap, has announced the amendments to the “Taiwan Stock Exchange Corporation Rules Governing the Preparation and Filing of Corporate Social Responsibility Reports by TWSE Listed Companies.” This provides guidelines on report preparation to enterprises that meet practical needs and be in line with international disclosure trends in order to help enterprises focus on sustainable development and fulfilling corporate social responsibility. The revised Rules shall be implemented from the date of the announcement.', 'Taiwan', 'climate', 'in_force', '2015-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_3', ARRAY['other sustainability policy', 'taiwan', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1064d2e8-6a57-562c-b2a4-46790c06231e', 'Taiwan Corporate Governance Best-Practice Principles for Futures Commission Merchants', 'Corporate Governance Best-Practice Principles for Futures Commission Merchants, 2015', 'CSR best practice principles, originally drafted by the Taiwan Business Council for Sustainable Development and the Taiwan CSR Institute.', 'CSR best practice principles, originally drafted by the Taiwan Business Council for Sustainable Development and the Taiwan CSR Institute.', 'CSR best practice principles, originally drafted by the Taiwan Business Council for Sustainable Development and the Taiwan CSR Institute.', 'Taiwan', 'governance', 'in_force', '2015-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_9', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f79a9416-e659-54cb-8d15-224fff6b0a01', 'Taiwan Corporate Social Responsibility Best Practice Principles for TWSE/GTSM-Listed', 'Corporate Social Responsibility Best Practice Principles for TWSE/GTSM-Listed Companies, 2014', 'In order to assist companies listed on the Taiwan Stock Exchange Corporation ("TWSE") and GreTai Securities Market ("GTSM") (collectively referred to as "TWSE/GTSM listed companies") to fulfil their corporate social responsibility initiatives and to promote economic, environmental, and social advancement for purposes of sustainable development, the TWSE and GTSM hereby jointly adopt the Principles to be followed by TWSE/GTSM listed companies. TWSE/GTSM listed companies are advised to promulgate their own corporate social responsibility principles in accordance with the Principles to manage their economic, environmental and social risks and impact.', 'In order to assist companies listed on the Taiwan Stock Exchange Corporation ("TWSE") and GreTai Securities Market ("GTSM") (collectively referred to as "TWSE/GTSM listed companies") to fulfil their corporate social responsibility initiatives and to promote economic, environmental, and social advancement for purposes of sustainable development, the TWSE and GTSM hereby jointly adopt the Principles to be followed by TWSE/GTSM listed companies. TWSE/GTSM listed companies are advised to promulgate their own corporate social responsibility principles in accordance with the Principles to manage their economic, environmental and social risks and impact.', 'In order to assist companies listed on the Taiwan Stock Exchange Corporation ("TWSE") and GreTai Securities Market ("GTSM") (collectively referred to as "TWSE/GTSM listed companies") to fulfil their corporate social responsibility initiatives and to promote economic, environmental, and social advancement for purposes of sustainable development, the TWSE and GTSM hereby jointly adopt the Principles to be followed by TWSE/GTSM listed companies. TWSE/GTSM listed companies are advised to promulgate their own corporate social responsibility principles in accordance with the Principles to manage their economic, environmental and social risks and impact.', 'Taiwan', 'climate', 'in_force', '2014-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_4', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3224e42e-f23a-5de7-8fcd-8eb4f17f4de8', 'Taiwan Corporate Governance Best Practice Principles for TSEC/GTSM Listed', 'Corporate Governance Best Practice Principles for TSEC/GTSM Listed Companies, 2010', 'To establish a sound corporate governance system, and to promote the integrity of the securities market, the TSEC and GTSM hereby jointly adopt the Principles to be followed by TSEC/GTSM listed companies. TSEC/GTSM listed companies are advised to promulgate their own corporate governance principles in accordance with the Principles.', 'To establish a sound corporate governance system, and to promote the integrity of the securities market, the TSEC and GTSM hereby jointly adopt the Principles to be followed by TSEC/GTSM listed companies. TSEC/GTSM listed companies are advised to promulgate their own corporate governance principles in accordance with the Principles.', 'To establish a sound corporate governance system, and to promote the integrity of the securities market, the TSEC and GTSM hereby jointly adopt the Principles to be followed by TSEC/GTSM listed companies. TSEC/GTSM listed companies are advised to promulgate their own corporate governance principles in accordance with the Principles.', 'Taiwan', 'governance', 'in_force', '2010-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_1', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('64c65a46-33cf-5d3f-8dce-10beebf58acf', 'Taiwan Corporate Governance Best-Practice Principles for SITEs/SICEs', 'Corporate Governance Best-Practice Principles for SITEs/SICEs, 2008', 'In order to assist securities investment trust enterprises ("SITEs") and securities investment consulting enterprises ("SICEs") conducting discretionary investment business (hereinafter collectively referred to as the "Member companies") to establish a sound corporate governance system, protect investors'' interests, and promote a healthy development of the securities market, the Securities Investment Trust and Consulting Association of the R.O.C. ("SITCA") hereby adopts the Principles as a guideline for Member companies'' reference.', 'In order to assist securities investment trust enterprises ("SITEs") and securities investment consulting enterprises ("SICEs") conducting discretionary investment business (hereinafter collectively referred to as the "Member companies") to establish a sound corporate governance system, protect investors'' interests, and promote a healthy development of the securities market, the Securities Investment Trust and Consulting Association of the R.O.C. ("SITCA") hereby adopts the Principles as a guideline for Member companies'' reference.', 'In order to assist securities investment trust enterprises ("SITEs") and securities investment consulting enterprises ("SICEs") conducting discretionary investment business (hereinafter collectively referred to as the "Member companies") to establish a sound corporate governance system, protect investors'' interests, and promote a healthy development of the securities market, the Securities Investment Trust and Consulting Association of the R.O.C. ("SITCA") hereby adopts the Principles as a guideline for Member companies'' reference.', 'Taiwan', 'governance', 'in_force', '2008-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_7', ARRAY['sdg3', 'other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c688baf7-d9e5-5bd9-aee5-cffc4e7ffb5e', 'Corporate Governance in Taiwan', 'Corporate Governance in Taiwan, 2007', 'An overview of corporate governance in Taiwan.', 'An overview of corporate governance in Taiwan.', 'An overview of corporate governance in Taiwan.', 'Taiwan', 'governance', 'in_force', '2007-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_11', ARRAY['other sustainability policy', 'taiwan', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('280c6f27-0767-5d79-8156-a2971172bcd1', 'Taiwan Corporate Governance Best-Practice Principles for Securities Firms', 'Corporate Governance Best-Practice Principles for Securities Firms, 2004', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'In order to assist securities firms to establish a sound corporate governance system, and to promote the integrity of the securities market, the Taiwan Stock Exchange ("TSE"), the GreTai Securities Market ("GTSM") and the Chinese Securities Association ("CSA") hereby jointly adopt the Principles to be followed by securities firms.', 'Taiwan', 'governance', 'in_force', '2004-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_8', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f8070e1f-1728-5ea9-abe7-8cbe8e00a5e1', 'Taiwan Corporate Governance Best-Practice Principles', 'Taiwan Corporate Governance Best-Practice Principles 2002', 'In order to assist companies listed on the Taiwan Stock Exchange ("TSE") and the GreTai Securities Market ("GTSM", collectively referred to as "TSE/GTSM listed companies") to establish a sound corporate governance system, and to promote the integrity of the securities market, the TSE and GTSM hereby jointly adopt the Principles to be followed by TSE/GTSM listed companies.', 'In order to assist companies listed on the Taiwan Stock Exchange ("TSE") and the GreTai Securities Market ("GTSM", collectively referred to as "TSE/GTSM listed companies") to establish a sound corporate governance system, and to promote the integrity of the securities market, the TSE and GTSM hereby jointly adopt the Principles to be followed by TSE/GTSM listed companies.', 'In order to assist companies listed on the Taiwan Stock Exchange ("TSE") and the GreTai Securities Market ("GTSM", collectively referred to as "TSE/GTSM listed companies") to establish a sound corporate governance system, and to promote the integrity of the securities market, the TSE and GTSM hereby jointly adopt the Principles to be followed by TSE/GTSM listed companies.', 'Taiwan', 'governance', 'in_force', '2002-01-01'::date, 'Taiwan', 'https://www.carrotsandsticks.org/policies/174_13', ARRAY['other sustainability policy', 'regulations', 'taiwan', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('171579e0-fac9-568a-b029-e65d52f0d489', 'Tanzania Dar Es Salaam Stock Exchange PLC Rules', 'Dar Es Salaam Stock Exchange PLC Rules 2022', 'The "Dar Es Salaam Stock Exchange PLC Rules" 2022 is a set of regulations issued by the Dar Es Salaam Stock Exchange in Tanzania. The rules provide guidance on the trading of securities on the stock exchange and cover a wide range of areas, including listing requirements, trading procedures, disclosure requirements, and market misconduct. The rules aim to promote fair and transparent trading practices, protect investors'' interests, and enhance the credibility of the stock exchange. The regulations apply to all listed companies, brokers, dealers, and other market participants operating on the Dar Es Salaam Stock Exchange.', 'The "Dar Es Salaam Stock Exchange PLC Rules" 2022 is a set of regulations issued by the Dar Es Salaam Stock Exchange in Tanzania. The rules provide guidance on the trading of securities on the stock exchange and cover a wide range of areas, including listing requirements, trading procedures, disclosure requirements, and market misconduct. The rules aim to promote fair and transparent trading practices, protect investors'' interests, and enhance the credibility of the stock exchange. The regulations apply to all listed companies, brokers, dealers, and other market participants operating on the Dar Es Salaam Stock Exchange.', 'The "Dar Es Salaam Stock Exchange PLC Rules" 2022 is a set of regulations issued by the Dar Es Salaam Stock Exchange in Tanzania. The rules provide guidance on the trading of securities on the stock exchange and cover a wide range of areas, including listing requirements, trading procedures, disclosure requirements, and market misconduct. The rules aim to promote fair and transparent trading practices, protect investors'' interests, and enhance the credibility of the stock exchange. The regulations apply to all listed companies, brokers, dealers, and other market participants operating on the Dar Es Salaam Stock Exchange.', 'Tanzania', 'governance', 'in_force', '2022-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_14', ARRAY['disclosure', 'mandatory', 'regulations', 'tanzania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46d41c1f-0e2c-55ce-9fad-17a96f59b875', 'Tanzania Mining (Local Content) Regulations', 'The Mining (Local Content) Regulations, 2018', 'These Regulations apply to local content with respect to mining activities. One of the objectives is to provide for a robust and transparent monitoring and reporting system to ensure delivery of local content policy objectives. A contractor, subcontractor, licensee or other allied entity shall within forty-five days of the beginning of each year after commencement of mining activities submit to the Commission an annual Local Content Performance Report covering all its projects and activities for the year under review which will specify by category of expenditure the local content on both current and cumulative cost basis; and show the employment achievement in terms of hours worked by Tanzanians and foreigners as well as their job positions and remuneration.', 'These Regulations apply to local content with respect to mining activities. One of the objectives is to provide for a robust and transparent monitoring and reporting system to ensure delivery of local content policy objectives. A contractor, subcontractor, licensee or other allied entity shall within forty-five days of the beginning of each year after commencement of mining activities submit to the Commission an annual Local Content Performance Report covering all its projects and activities for the year under review which will specify by category of expenditure the local content on both current and cumulative cost basis; and show the employment achievement in terms of hours worked by Tanzanians and foreigners as well as their job positions and remuneration.', 'These Regulations apply to local content with respect to mining activities. One of the objectives is to provide for a robust and transparent monitoring and reporting system to ensure delivery of local content policy objectives. A contractor, subcontractor, licensee or other allied entity shall within forty-five days of the beginning of each year after commencement of mining activities submit to the Commission an annual Local Content Performance Report covering all its projects and activities for the year under review which will specify by category of expenditure the local content on both current and cumulative cost basis; and show the employment achievement in terms of hours worked by Tanzanians and foreigners as well as their job positions and remuneration.', 'Tanzania', 'climate', 'in_force', '2018-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_12', ARRAY['sdg8', 'tanzania', 'other sustainability policy', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e1411d87-3845-570b-b038-ec696ae5518b', 'Tanzania Public Limited Company Rules', 'Public Limited Company Rules, 2016', 'The Dar es Salaam Stock Exchange Public Limited Company Rules set out the required practices and behavior for companies listed on the stock exchange. Key to ensuring the efficient and effective functioning of the stock market is corporate disclosure, which these listing rules stipulate. All listed companies are required to produce audited annual reports in accordance with the rules set by the Companies Act. In addition, listed companies are required to disclose how they comply with the Guidelines on Corporate Governance Practices by Public Listed Companies in Tanzania in their annual report.', 'The Dar es Salaam Stock Exchange Public Limited Company Rules set out the required practices and behavior for companies listed on the stock exchange. Key to ensuring the efficient and effective functioning of the stock market is corporate disclosure, which these listing rules stipulate. All listed companies are required to produce audited annual reports in accordance with the rules set by the Companies Act. In addition, listed companies are required to disclose how they comply with the Guidelines on Corporate Governance Practices by Public Listed Companies in Tanzania in their annual report.', 'The Dar es Salaam Stock Exchange Public Limited Company Rules set out the required practices and behavior for companies listed on the stock exchange. Key to ensuring the efficient and effective functioning of the stock market is corporate disclosure, which these listing rules stipulate. All listed companies are required to produce audited annual reports in accordance with the rules set by the Companies Act. In addition, listed companies are required to disclose how they comply with the Guidelines on Corporate Governance Practices by Public Listed Companies in Tanzania in their annual report.', 'Tanzania', 'climate', 'in_force', '2016-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_10', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23009e4a-983b-584f-ad52-9101971f732f', 'Tanzania Occupational Safety and Health (Notification of Occupational Diseases', 'Occupational Safety and Health (Notification of Occupational Diseases, Injuries and Dangerous Occurences) Rules, 2016', 'These Rules, issued in 2016, develop and refine the reporting requirements set by the Occupational Health and Safety Act of 2003. Article 3, 4 and 5 of the Rules determine the means and process by which companies are to report of injury or dangerous occurrence, death of an employee, and cases of occupational disease. In addition, all companies are required to report to the Chief Inspector in cases of gas incidents. Part II of the Rules determines those incidents which are deemed to be dangerous and, therefore, require notification. Parts IV, V and VI further specifies what are dangerous incidents for mines, quarries and offshore facilities, respectively. Finally, the First Schedule of the Rules provides a full and detailed list of all reportable occupational diseases, while the Second Schedule provides the template for reporting on injury or dangerous occurrences, as required by Article 3.', 'These Rules, issued in 2016, develop and refine the reporting requirements set by the Occupational Health and Safety Act of 2003. Article 3, 4 and 5 of the Rules determine the means and process by which companies are to report of injury or dangerous occurrence, death of an employee, and cases of occupational disease. In addition, all companies are required to report to the Chief Inspector in cases of gas incidents. Part II of the Rules determines those incidents which are deemed to be dangerous and, therefore, require notification. Parts IV, V and VI further specifies what are dangerous incidents for mines, quarries and offshore facilities, respectively. Finally, the First Schedule of the Rules provides a full and detailed list of all reportable occupational diseases, while the Second Schedule provides the template for reporting on injury or dangerous occurrences, as required by Article 3.', 'These Rules, issued in 2016, develop and refine the reporting requirements set by the Occupational Health and Safety Act of 2003. Article 3, 4 and 5 of the Rules determine the means and process by which companies are to report of injury or dangerous occurrence, death of an employee, and cases of occupational disease. In addition, all companies are required to report to the Chief Inspector in cases of gas incidents. Part II of the Rules determines those incidents which are deemed to be dangerous and, therefore, require notification. Parts IV, V and VI further specifies what are dangerous incidents for mines, quarries and offshore facilities, respectively. Finally, the First Schedule of the Rules provides a full and detailed list of all reportable occupational diseases, while the Second Schedule provides the template for reporting on injury or dangerous occurrences, as required by Article 3.', 'Tanzania', 'climate', 'in_force', '2016-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_11', ARRAY['sdg8', 'tanzania', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46522d65-38ec-5145-9376-2a8b56b436b3', 'Tanzania Workers Compensation Act', 'The Workers Compensation Act, 2015', 'This document is concerned with an Act to provide for compensation to employees for disablement of death caused by or resulting from injuries or diseases sustained or contracted in the course of employment to establish the Fund for administration and regulation of workers compensation and to provide for related matter.', 'This document is concerned with an Act to provide for compensation to employees for disablement of death caused by or resulting from injuries or diseases sustained or contracted in the course of employment to establish the Fund for administration and regulation of workers compensation and to provide for related matter.', 'This document is concerned with an Act to provide for compensation to employees for disablement of death caused by or resulting from injuries or diseases sustained or contracted in the course of employment to establish the Fund for administration and regulation of workers compensation and to provide for related matter.', 'Tanzania', 'nature', 'in_force', '2015-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_6', ARRAY['sdg8', 'tanzania', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('503aa6cd-3815-5d27-b4c3-4579cadba0a5', 'Tanzania Extractive Industries (Transparency and Accountability) Act', 'The Tanzania Extractive Industries (Transparency and Accountability) Act, 2015', 'This document is concerned with an Act to provide for establishment of the Extractive Industries (Transparency and Accountability) Committee for purposes of ensuring transparency and accountability in extractive industries and to provide for other related matters.', 'This document is concerned with an Act to provide for establishment of the Extractive Industries (Transparency and Accountability) Committee for purposes of ensuring transparency and accountability in extractive industries and to provide for other related matters.', 'This document is concerned with an Act to provide for establishment of the Extractive Industries (Transparency and Accountability) Committee for purposes of ensuring transparency and accountability in extractive industries and to provide for other related matters.', 'Tanzania', 'climate', 'in_force', '2015-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_9', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb6735bf-f415-5131-93f9-184078cb9c2a', 'Tanzania Water Resources Management Act', 'The Water Resources Management Act, 2009', 'This document is concerned with an Act to provide for institutional and legal framework for sustainable management and development of water resources; to outline principles for water resources management; to provide for the prevention and control of water pollution; to provide for participation of stakeholders and the general public in implementation of the National Water Policy, repeal of the Water Utilization (Control and Regulation) Act and to provide for related matters.', 'This document is concerned with an Act to provide for institutional and legal framework for sustainable management and development of water resources; to outline principles for water resources management; to provide for the prevention and control of water pollution; to provide for participation of stakeholders and the general public in implementation of the National Water Policy, repeal of the Water Utilization (Control and Regulation) Act and to provide for related matters.', 'This document is concerned with an Act to provide for institutional and legal framework for sustainable management and development of water resources; to outline principles for water resources management; to provide for the prevention and control of water pollution; to provide for participation of stakeholders and the general public in implementation of the National Water Policy, repeal of the Water Utilization (Control and Regulation) Act and to provide for related matters.', 'Tanzania', 'governance', 'in_force', '2009-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_8', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6b7d7467-1d9d-5187-b133-c7da1ec0f7a1', 'Tanzania Petroleum Act', 'The Petroleum Act, 2008', 'This Act concerns the administration of and control on petroleum operations in Tanzania and assigns for this purpose duties to the Minister responsible for petroleum matters and the Energy and Water Utilities Regulatory Authority (EWURA).', 'This Act concerns the administration of and control on petroleum operations in Tanzania and assigns for this purpose duties to the Minister responsible for petroleum matters and the Energy and Water Utilities Regulatory Authority (EWURA).', 'This Act concerns the administration of and control on petroleum operations in Tanzania and assigns for this purpose duties to the Minister responsible for petroleum matters and the Energy and Water Utilities Regulatory Authority (EWURA).', 'Tanzania', 'climate', 'in_force', '2008-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_7', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8347380d-fb72-5cef-bc6e-e8ed04e7bcf6', 'Tanzania Environmental Management (Air Quality Standards) Regulations', 'The Environmental Management (Air Quality Standards) Regulations, 2007', 'These Regulations, made by the Minister of State responsible for the environment under sections 143, 144 and 230 of the Environmental Management Act, concern the prevention and control of air pollution and require the National Environmental Standards Committee to, among other things: prescribe criteria and procedure for measurement for air quality; (b) establish ambient air quality standards; (c) establish emission standard for various sources of air pollution. They also define enforcement powers of the National Environment Management Council, defines offences and provide for appeal against decisions of the decision of the Council, an Environmental Inspector or local Environment Management Officers to the Minister and appeal against the decision of the Minister with the Environmental Appeals Tribunal.', 'These Regulations, made by the Minister of State responsible for the environment under sections 143, 144 and 230 of the Environmental Management Act, concern the prevention and control of air pollution and require the National Environmental Standards Committee to, among other things: prescribe criteria and procedure for measurement for air quality; (b) establish ambient air quality standards; (c) establish emission standard for various sources of air pollution. They also define enforcement powers of the National Environment Management Council, defines offences and provide for appeal against decisions of the decision of the Council, an Environmental Inspector or local Environment Management Officers to the Minister and appeal against the decision of the Minister with the Environmental Appeals Tribunal.', 'These Regulations, made by the Minister of State responsible for the environment under sections 143, 144 and 230 of the Environmental Management Act, concern the prevention and control of air pollution and require the National Environmental Standards Committee to, among other things: prescribe criteria and procedure for measurement for air quality; (b) establish ambient air quality standards; (c) establish emission standard for various sources of air pollution. They also define enforcement powers of the National Environment Management Council, defines offences and provide for appeal against decisions of the decision of the Council, an Environmental Inspector or local Environment Management Officers to the Minister and appeal against the decision of the Minister with the Environmental Appeals Tribunal.', 'Tanzania', 'governance', 'in_force', '2007-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_5', ARRAY['tanzania', 'voluntary', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b364081d-f400-5918-af73-f9da4fdcf00d', 'Tanzania Environmental Management Act', 'The Environmental Management Act, 2004', 'An Act to provide for legal and institutional framework for sustainable management of environment; to outline principles for management, impact and risk assessments, prevention and control of pollution, waste management, environmental quality standards, public participation, compliance and enforcement; to provide a basis for implementation of international instruments of environment; to provide for implementation of the National Environment Policy; to repeal the National Environment Management Act, 1983 and to provide for continued existence of the National Environment Management Council; to provide for the establishment of the National Environmental Trust Fund and to provide for other related matters.', 'An Act to provide for legal and institutional framework for sustainable management of environment; to outline principles for management, impact and risk assessments, prevention and control of pollution, waste management, environmental quality standards, public participation, compliance and enforcement; to provide a basis for implementation of international instruments of environment; to provide for implementation of the National Environment Policy; to repeal the National Environment Management Act, 1983 and to provide for continued existence of the National Environment Management Council; to provide for the establishment of the National Environmental Trust Fund and to provide for other related matters.', 'An Act to provide for legal and institutional framework for sustainable management of environment; to outline principles for management, impact and risk assessments, prevention and control of pollution, waste management, environmental quality standards, public participation, compliance and enforcement; to provide a basis for implementation of international instruments of environment; to provide for implementation of the National Environment Policy; to repeal the National Environment Management Act, 1983 and to provide for continued existence of the National Environment Management Council; to provide for the establishment of the National Environmental Trust Fund and to provide for other related matters.', 'Tanzania', 'circularity', 'in_force', '2004-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_4', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('057a4d20-d71a-5649-b52a-960fed21fd9c', 'Tanzania Occupational Health and Safety Act', 'The Occupational Health and Safety Act, 2003', 'This document is concerned with an Act to repeal the Factories Ordinance; to make provisions for the safety, health and welfare of persons at work in factories and other places of work to provide for the protection of persons other than persons at work against hazards to health and safety arising out of or in connection with activities of persons at work; and to provide for connected matters.', 'This document is concerned with an Act to repeal the Factories Ordinance; to make provisions for the safety, health and welfare of persons at work in factories and other places of work to provide for the protection of persons other than persons at work against hazards to health and safety arising out of or in connection with activities of persons at work; and to provide for connected matters.', 'This document is concerned with an Act to repeal the Factories Ordinance; to make provisions for the safety, health and welfare of persons at work in factories and other places of work to provide for the protection of persons other than persons at work against hazards to health and safety arising out of or in connection with activities of persons at work; and to provide for connected matters.', 'Tanzania', 'social', 'in_force', '2003-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_2', ARRAY['sdg8', 'tanzania', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('28f7e5f8-ea60-5b73-af27-5929b29ce8ab', 'Tanzania Industrial and Consumer Chemicals (Management and Control) Act', 'The Industrial and Consumer Chemicals (Management and Control) Act, 2003', 'This document is concerned with an Act to provide for the management and control of the production, importation, transportation, exportation, storage, dealing, and disposal of chemicals and for matters connected therewith.', 'This document is concerned with an Act to provide for the management and control of the production, importation, transportation, exportation, storage, dealing, and disposal of chemicals and for matters connected therewith.', 'This document is concerned with an Act to provide for the management and control of the production, importation, transportation, exportation, storage, dealing, and disposal of chemicals and for matters connected therewith.', 'Tanzania', 'climate', 'in_force', '2003-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_3', ARRAY['tanzania', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bd7434e2-560f-5d7d-8dec-90784ceecf20', 'Tanzania Companies Act', 'The Companies Act, 2002', 'The Companies Act, issued in 2002, sets out a comprehensive framework for the regulation and control of companies and associations in Tanzania. The Act covers types of company, processes for starting and winding up, formalities for carrying out business, shareholders, meetings and dividends, rules for governance, and accounts and reporting. With regard to reporting, the Companies Act determines the content of an annual report for companies in Tanzania: annual accounts, directors'' report and auditor''s report. The directors'' report is to supplement and contextualize the financial accounts, providing readers with an understanding of how the company is performing and developing. Requirements for each of these components are stipulated in Chapter V of the Companies Act, with further details provided in further articles of the Act. The annual report is to be delivered to shareholders as well as the Registrar.', 'The Companies Act, issued in 2002, sets out a comprehensive framework for the regulation and control of companies and associations in Tanzania. The Act covers types of company, processes for starting and winding up, formalities for carrying out business, shareholders, meetings and dividends, rules for governance, and accounts and reporting. With regard to reporting, the Companies Act determines the content of an annual report for companies in Tanzania: annual accounts, directors'' report and auditor''s report. The directors'' report is to supplement and contextualize the financial accounts, providing readers with an understanding of how the company is performing and developing. Requirements for each of these components are stipulated in Chapter V of the Companies Act, with further details provided in further articles of the Act. The annual report is to be delivered to shareholders as well as the Registrar.', 'The Companies Act, issued in 2002, sets out a comprehensive framework for the regulation and control of companies and associations in Tanzania. The Act covers types of company, processes for starting and winding up, formalities for carrying out business, shareholders, meetings and dividends, rules for governance, and accounts and reporting. With regard to reporting, the Companies Act determines the content of an annual report for companies in Tanzania: annual accounts, directors'' report and auditor''s report. The directors'' report is to supplement and contextualize the financial accounts, providing readers with an understanding of how the company is performing and developing. Requirements for each of these components are stipulated in Chapter V of the Companies Act, with further details provided in further articles of the Act. The annual report is to be delivered to shareholders as well as the Registrar.', 'Tanzania', 'climate', 'in_force', '2002-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_13', ARRAY['tanzania', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0acd46b-4039-5d9d-a19f-3477c945dfe4', 'Corporate Governance Practices by Public Listed Companies in Tanzania', 'Guidelines on Corporate Governance Practices by Public Listed Companies in Tanzania, 1994', 'The Capital Markets and Securities Authority has developed these guidelines for good corporate governance practices by public listed companies in Tanzania in response to the growing importance of  governance issues both in emerging and developing economies and for  promoting domestic and regional capital markets growth. It is also in recognition of the role of good governance in corporate performance, capital formation and maximization of shareholders value as well as protection of investors’ rights.', 'The Capital Markets and Securities Authority has developed these guidelines for good corporate governance practices by public listed companies in Tanzania in response to the growing importance of  governance issues both in emerging and developing economies and for  promoting domestic and regional capital markets growth. It is also in recognition of the role of good governance in corporate performance, capital formation and maximization of shareholders value as well as protection of investors’ rights.', 'The Capital Markets and Securities Authority has developed these guidelines for good corporate governance practices by public listed companies in Tanzania in response to the growing importance of  governance issues both in emerging and developing economies and for  promoting domestic and regional capital markets growth. It is also in recognition of the role of good governance in corporate performance, capital formation and maximization of shareholders value as well as protection of investors’ rights.', 'Tanzania', 'climate', 'in_force', '1994-01-01'::date, 'Tanzania', 'https://www.carrotsandsticks.org/policies/176_1', ARRAY['tanzania', 'regulations', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed66f4c5-f022-5965-836e-16efd5b582b7', 'TCFD Task Force on Climate-related Financial Disclosures Guidance', 'Task Force on Climate-related Financial Disclosures Guidance on Risk Management Integration and Disclosure', 'This 2020 guidance is aimed at companies interested in integrating climate-related risks into their existing risk management processes and disclosing information on their risk management processes in alignment with the Task Force’s recommendations.', 'This 2020 guidance is aimed at companies interested in integrating climate-related risks into their existing risk management processes and disclosing information on their risk management processes in alignment with the Task Force’s recommendations.', 'This 2020 guidance is aimed at companies interested in integrating climate-related risks into their existing risk management processes and disclosing information on their risk management processes in alignment with the Task Force’s recommendations.', 'TCFD', 'climate', 'in_force', '2020-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_3', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'tcfd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08c93edc-fadf-5067-964c-81e0d6f6be6d', 'TCFD Scenario Analysis for Non Financial Companaies', 'Guidance on Scenario Analysis for Non Financial Companaies', 'This 2020 guidance is intended to assist non-financial companies interested in using climate-related scenarios as part of their efforts to implement the Task Force’s recommendations. The scenario analysis guidance provides practical, process-oriented ways for companies to use climate-related scenario analysis and ideas for disclosing the resilience of their strategies to different climate-related scenarios.', 'This 2020 guidance is intended to assist non-financial companies interested in using climate-related scenarios as part of their efforts to implement the Task Force’s recommendations. The scenario analysis guidance provides practical, process-oriented ways for companies to use climate-related scenario analysis and ideas for disclosing the resilience of their strategies to different climate-related scenarios.', 'This 2020 guidance is intended to assist non-financial companies interested in using climate-related scenarios as part of their efforts to implement the Task Force’s recommendations. The scenario analysis guidance provides practical, process-oriented ways for companies to use climate-related scenario analysis and ideas for disclosing the resilience of their strategies to different climate-related scenarios.', 'TCFD', 'climate', 'in_force', '2020-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_6', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'tcfd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ebce49d3-e705-545a-a8d3-00ee77ba5e47', 'Climate-related Financial Disclosures 2.0 TCFD Guidance 2.0', 'Guidance on Climate-related Financial Disclosures 2.0 TCFD Guidance 2.0', 'The TCFD recommendations are deemed to be a useful set of tools for dialogue between companies and investors and other stakeholders. The utility of the recommendations lies in their scope as an international framework commissioned by the G20, and there is a current movement to integrate them into global frameworks for corporate evaluation and national and regional systems.', 'The TCFD recommendations are deemed to be a useful set of tools for dialogue between companies and investors and other stakeholders. The utility of the recommendations lies in their scope as an international framework commissioned by the G20, and there is a current movement to integrate them into global frameworks for corporate evaluation and national and regional systems.', 'The TCFD recommendations are deemed to be a useful set of tools for dialogue between companies and investors and other stakeholders. The utility of the recommendations lies in their scope as an international framework commissioned by the G20, and there is a current movement to integrate them into global frameworks for corporate evaluation and national and regional systems.', 'TCFD', 'climate', 'in_force', '2020-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_8', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'tcfd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3552e575-5ed8-5fc9-a385-e1ec80c5095a', 'TCFD Utilizing Climate-related Information to Promote Green Investment (Green', 'Guidance for Utilizing Climate-related Information to Promote Green Investment (Green Investment Guidance)', 'This Guidance provides commentary on perspectives needed by investors and other stakeholders when understanding the information disclosed based on the TCFD recommendations. To help investors and other stakeholders better understand information disclosed, this Guidance also provides examples of investment practices utilizing that information as well as viewpoints on assessments that recognize industry-specific situations while considering the alignment between the TCFD Recommendations and discussions about current state of corporate disclosure such as integrated reporting.', 'This Guidance provides commentary on perspectives needed by investors and other stakeholders when understanding the information disclosed based on the TCFD recommendations. To help investors and other stakeholders better understand information disclosed, this Guidance also provides examples of investment practices utilizing that information as well as viewpoints on assessments that recognize industry-specific situations while considering the alignment between the TCFD Recommendations and discussions about current state of corporate disclosure such as integrated reporting.', 'This Guidance provides commentary on perspectives needed by investors and other stakeholders when understanding the information disclosed based on the TCFD recommendations. To help investors and other stakeholders better understand information disclosed, this Guidance also provides examples of investment practices utilizing that information as well as viewpoints on assessments that recognize industry-specific situations while considering the alignment between the TCFD Recommendations and discussions about current state of corporate disclosure such as integrated reporting.', 'TCFD', 'climate', 'in_force', '2019-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_7', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'tcfd', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aadc7e77-674f-5359-a42a-bd63f9e3e3fd', 'TCFD Recommendations of the Task Force on Climate-related Financial', 'Recommendations of the Task Force on Climate-related Financial Disclosures', 'The TCFD recommendations aim to provide a standardized framework for climate-related financial disclosures that are decision-useful for investors, lenders, and insurers. Structured around four thematic areas—Governance, Strategy, Risk Management, and Metrics and Targets—the framework provides guidance for companies across sectors and jurisdictions. The report emphasizes voluntary, forward-looking disclosures that enable stakeholders to assess climate-related risks and opportunities. The recommendations promote integrating these disclosures into mainstream annual financial filings, ensuring robust governance processes. Supplementary guidance is provided for high-impact industries, such as energy, transportation, and agriculture, due to their significant greenhouse gas emissions. The TCFD also highlights the importance of scenario analysis and alignment with global frameworks like the Paris Agreement, to foster financial system stability and support the transition to a low-carbon economy.', 'The TCFD recommendations aim to provide a standardized framework for climate-related financial disclosures that are decision-useful for investors, lenders, and insurers. Structured around four thematic areas—Governance, Strategy, Risk Management, and Metrics and Targets—the framework provides guidance for companies across sectors and jurisdictions. The report emphasizes voluntary, forward-looking disclosures that enable stakeholders to assess climate-related risks and opportunities. The recommendations promote integrating these disclosures into mainstream annual financial filings, ensuring robust governance processes. Supplementary guidance is provided for high-impact industries, such as energy, transportation, and agriculture, due to their significant greenhouse gas emissions. The TCFD also highlights the importance of scenario analysis and alignment with global frameworks like the Paris Agreement, to foster financial system stability and support the transition to a low-carbon economy.', 'The TCFD recommendations aim to provide a standardized framework for climate-related financial disclosures that are decision-useful for investors, lenders, and insurers. Structured around four thematic areas—Governance, Strategy, Risk Management, and Metrics and Targets—the framework provides guidance for companies across sectors and jurisdictions. The report emphasizes voluntary, forward-looking disclosures that enable stakeholders to assess climate-related risks and opportunities. The recommendations promote integrating these disclosures into mainstream annual financial filings, ensuring robust governance processes. Supplementary guidance is provided for high-impact industries, such as energy, transportation, and agriculture, due to their significant greenhouse gas emissions. The TCFD also highlights the importance of scenario analysis and alignment with global frameworks like the Paris Agreement, to foster financial system stability and support the transition to a low-carbon economy.', 'TCFD', 'climate', 'in_force', '2017-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_1', ARRAY['guidance_frameworks', 'sdg13', 'sdg2', 'sdg7', 'sdg11', 'tcfd', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
